//! `classgroup-structure` — structure of `Cl(D_K)` given its order `h` (from the
//! relation run of the `classgroup` binary): the factorisation of `h`, the genus
//! 2-rank, the Sylow invariants of every prime part that is small enough to
//! enumerate, and the order and index of the subgroup generated by the prime
//! ideals above the split primes up to each bound (and above Mazur's primes).
//!
//! Usage:
//!   classgroup-structure --label L (--p P --n N | --disc D) --h H
//!                        [--bound 2000] [--sub-bounds 50,163,691,2000] [--out file.json]
//!
//! The subgroup orders are exact given `h` and its complete factorisation; they
//! never assume cyclicity. A Sylow part larger than `MAX_ENUMERATED_SYLOW` is
//! reported as not enumerated and the corresponding index as null.

use crypto_lib::isogeny::class_group::BinaryQuadraticForm;
use crypto_lib::isogeny::class_group_subexp::{
    factor_base, factor_big, is_probable_prime_pub, subgroup_order, sylow_invariants, Splitting,
};
use num_bigint::{BigInt, BigUint};
use num_integer::Integer;
use num_traits::{One, Signed};
use std::collections::BTreeMap;

const MAZUR_ODD: &[u64] = &[3, 5, 7, 11, 13, 17, 19, 37, 43, 67, 163];

fn parse_big(s: &str) -> BigInt {
    let s = s.trim();
    if let Some(h) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        BigInt::parse_bytes(h.as_bytes(), 16).expect("hex integer")
    } else {
        BigInt::parse_bytes(s.as_bytes(), 10).expect("decimal integer")
    }
}

/// `D_K` and the conductor of the order of discriminant `delta`.
fn fundamental_part(delta: &BigInt) -> (BigInt, BigUint, Vec<(BigUint, u32)>) {
    let (factors, complete) = factor_big(delta.magnitude());
    assert!(complete, "Delta did not factor completely");
    let mut f = BigUint::one();
    let mut core = BigUint::one();
    for (p, e) in &factors {
        f *= p.pow(e / 2);
        if e % 2 == 1 {
            core *= p;
        }
    }
    let mut dk = -BigInt::from(core);
    if dk.mod_floor(&BigInt::from(4)) != BigInt::one() {
        dk *= 4;
        f /= BigUint::from(2u32);
    }
    (dk, f, factors)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut opts: BTreeMap<String, String> = BTreeMap::new();
    let mut i = 1;
    while i < args.len() {
        opts.insert(
            args[i].trim_start_matches("--").to_string(),
            args.get(i + 1).cloned().unwrap_or_default(),
        );
        i += 2;
    }
    let label = opts.get("label").cloned().unwrap_or_else(|| "disc".into());
    let delta = if let Some(d) = opts.get("disc") {
        parse_big(d)
    } else {
        let p = parse_big(opts.get("p").expect("--p or --disc"));
        let n = parse_big(opts.get("n").expect("--n"));
        let t = &p + BigInt::one() - &n;
        &t * &t - BigInt::from(4) * &p
    };
    assert!(delta.is_negative());
    // The fundamental discriminant needs the squarefree part of Δ. For the
    // 226–258-bit discriminants Pollard–Brent cannot split a cofactor with two
    // large prime factors, so the prime factors of D_K may be supplied
    // (--disc-primes, from PARI's `factor`, see data/cl/facts.jsonl) together
    // with --conductor; they are verified (each prime by Miller–Rabin, the
    // product against |D_K|) rather than trusted.
    let (dk, conductor, delta_factors) = match (opts.get("disc-primes"), opts.get("conductor")) {
        (Some(list), cond) => {
            let f: BigUint = cond.map_or(BigUint::one(), |c| parse_big(c).magnitude().clone());
            let dk_mag = delta.magnitude() / (&f * &f);
            let dk = BigInt::from_biguint(num_bigint::Sign::Minus, dk_mag);
            let primes: Vec<BigUint> = list
                .split(',')
                .filter(|t| !t.trim().is_empty())
                .map(|t| parse_big(t).magnitude().clone())
                .collect();
            let mut prod = BigUint::one();
            for q in &primes {
                assert!(
                    is_probable_prime_pub(q),
                    "--disc-primes entry is not prime: {q}"
                );
                prod *= q;
            }
            let mag = dk.magnitude().clone();
            // |D_K| is squarefree, or 4 times a squarefree odd number, or 8 times one
            let ok = prod == mag
                || &prod * BigUint::from(2u32) == mag
                || &prod * BigUint::from(4u32) == mag;
            assert!(
                ok,
                "--disc-primes do not multiply to |D_K| (up to the power of 2)"
            );
            let mut factors: Vec<(BigUint, u32)> =
                primes.iter().map(|q| (q.clone(), 1u32)).collect();
            let two = BigUint::from(2u32);
            let v2 = mag.trailing_zeros().unwrap_or(0) as u32;
            if v2 > 0 && !primes.contains(&two) {
                factors.push((two.clone(), v2));
            }
            factors.sort();
            // delta_factors are those of Δ = f² D_K: add the conductor's primes with exponent 2
            let (ff, complete) = factor_big(&f);
            assert!(complete, "conductor did not factor");
            for (q, e) in ff {
                if let Some(entry) = factors.iter_mut().find(|(p, _)| *p == q) {
                    entry.1 += 2 * e;
                } else {
                    factors.push((q, 2 * e));
                }
            }
            factors.sort();
            (dk, f, factors)
        }
        _ => fundamental_part(&delta),
    };
    let h: BigUint = parse_big(opts.get("h").expect("--h")).magnitude().clone();
    let bound: u64 = opts.get("bound").map_or(2000, |s| s.parse().unwrap());
    let sub_bounds: Vec<u64> = opts
        .get("sub-bounds")
        .map(|s| s.split(',').map(|x| x.trim().parse().unwrap()).collect())
        .unwrap_or_else(|| vec![50, 163, 691, 2000]);

    let (h_factors, h_complete) = factor_big(&h);
    assert!(h_complete, "h did not factor completely");
    // genus theory: the 2-rank is mu - 1 for mu assigned characters
    let odd_primes = delta_factors
        .iter()
        .filter(|(p, e)| e % 2 == 1 && *p != BigUint::from(2u32))
        .count();
    let two_rank_genus = (odd_primes + usize::from(dk.is_even())).saturating_sub(1);

    let fb = factor_base(&dk, bound);
    let split_odd: Vec<(u64, BinaryQuadraticForm)> = fb
        .iter()
        .filter(|fp| fp.p > 2 && fp.kind == Splitting::Split)
        .map(|fp| (fp.p, fp.form.clone()))
        .collect();
    let all: Vec<(u64, BinaryQuadraticForm)> =
        fb.iter().map(|fp| (fp.p, fp.form.clone())).collect();

    // Sylow invariants of the subgroup generated by every factor-base form up to the bound
    let all_forms: Vec<BinaryQuadraticForm> = all.iter().map(|(_, f)| f.clone()).collect();
    let mut sylow = Vec::new();
    for (q, e) in &h_factors {
        if *e == 1 && q.bits() > 20 {
            continue; // a large prime dividing h once: cyclic of order q, nothing to enumerate
        }
        let inv = sylow_invariants(&all_forms, &h, q, *e);
        sylow.push(format!(
            "{{\"q\": {}, \"e\": {}, \"invariant_exponents\": {}}}",
            q,
            e,
            inv.map_or("null".to_string(), |v| format!("{v:?}"))
        ));
    }

    let order_of = |forms: &[BinaryQuadraticForm]| -> Option<BigUint> {
        subgroup_order(forms, &h, &h_factors)
    };
    let fmt_idx = |ord: Option<BigUint>| -> String {
        ord.map_or("null".to_string(), |o| (&h / o).to_string())
    };
    let mut by_bound = Vec::new();
    for &b in &sub_bounds {
        let split_forms: Vec<BinaryQuadraticForm> = split_odd
            .iter()
            .filter(|(p, _)| *p <= b)
            .map(|(_, f)| f.clone())
            .collect();
        let all_forms_b: Vec<BinaryQuadraticForm> = all
            .iter()
            .filter(|(p, _)| *p <= b)
            .map(|(_, f)| f.clone())
            .collect();
        let so = order_of(&split_forms);
        let ao = order_of(&all_forms_b);
        by_bound.push(format!(
            "{{\"bound\": {b}, \"split_odd_primes\": {}, \"subgroup_order_split_odd\": {}, \"index_split_odd\": {}, \"index_all_primes\": {}}}",
            split_forms.len(),
            so.as_ref().map_or("null".to_string(), |o| o.to_string()),
            fmt_idx(so.clone()),
            fmt_idx(ao)
        ));
    }
    let mazur_forms: Vec<BinaryQuadraticForm> = split_odd
        .iter()
        .filter(|(p, _)| MAZUR_ODD.contains(p))
        .map(|(_, f)| f.clone())
        .collect();
    let mazur_primes: Vec<u64> = split_odd
        .iter()
        .map(|(p, _)| *p)
        .filter(|p| MAZUR_ODD.contains(p))
        .collect();
    let mazur_idx = fmt_idx(order_of(&mazur_forms));

    // smallest bound at which the split odd primes generate the whole group:
    // the subgroup order is monotone in the prefix length, so binary search it
    let mut generating: Option<u64> = None;
    {
        let order_prefix = |len: usize| -> Option<BigUint> {
            let forms: Vec<BinaryQuadraticForm> =
                split_odd.iter().take(len).map(|(_, f)| f.clone()).collect();
            order_of(&forms)
        };
        if order_prefix(split_odd.len()) == Some(h.clone()) {
            let (mut lo, mut hi) = (1usize, split_odd.len()); // invariant: order(hi) == h
            while lo < hi {
                let mid = (lo + hi) / 2;
                if order_prefix(mid) == Some(h.clone()) {
                    hi = mid;
                } else {
                    lo = mid + 1;
                }
            }
            generating = Some(split_odd[hi - 1].0);
        }
    }

    let json = format!(
        "{{\"label\": \"{label}\", \"D_K\": {dk}, \"conductor\": {conductor}, \"h\": {h}, \"h_factorisation\": {{\"primes\": [{}], \"exponents\": [{}]}}, \
\"two_rank_genus\": {two_rank_genus}, \"sylow\": [{}], \"by_bound\": [{}], \"mazur_split\": {:?}, \"index_mazur\": {mazur_idx}, \
\"smallest_split_prime_bound_generating\": {}, \"factor_base_bound\": {bound}}}",
        h_factors.iter().map(|(p, _)| p.to_string()).collect::<Vec<_>>().join(", "),
        h_factors.iter().map(|(_, e)| e.to_string()).collect::<Vec<_>>().join(", "),
        sylow.join(", "),
        by_bound.join(", "),
        mazur_primes,
        generating.map_or("null".to_string(), |p| p.to_string()),
    );
    println!("{json}");
    if let Some(path) = opts.get("out") {
        std::fs::write(path, format!("{json}\n")).expect("write --out");
    }
}
